# The previous script failed because `get_pins -of_objects [get_ports clk]` is not valid in OpenROAD 2.0.
# Ports don't have pins in the same way cells do. Instead, we should get the net connected to the port.
# We can use `get_nets -of_objects [get_ports clk]` to get the root clock net.
# Then we find the buffers driven by this net or subsequent nets in the clock tree.

# Step 1: Identify all clock buffer instances.
# The task states CTS used BUF_X4 buffers.
set buf_instances [get_cells -filter "cell_name==BUF_X4"]

# If no BUF_X4 instances are found, we might need to look for other buffer types.
# Let's check if there are any other buffer cells that are part of the clock tree.
# However, the prompt is specific about BUF_X4. Let's proceed with BUF_X4.
# If the list is empty, we'll try to find any buffer cell that is driven by a clock net.
if {[llength $buf_instances] == 0} {
    # Fallback: find all instances that are buffers and are part of the clock tree.
    # This is harder to define precisely without more info.
    # Let's assume the task guarantees BUF_X4 exists.
    puts "Warning: No BUF_X4 instances found. Trying to find any clock buffer."
    # Get all clock nets
    set clock_nets [all_clocks]
    set clk_net [lindex $clock_nets 0]
    # Get the net connected to the clk port
    set root_net [get_nets -of_objects [get_ports clk]]

    # Find all instances driven by the root_net or its descendants
    # This is complex. Let's try to find all instances of cell types that are buffers.
    # Common buffer cells: BUF_X*, CLKBUF_X*
    set all_buf_cells [get_cells -filter "is_buffer==true"]
    # This might not be a valid filter. Let's try to get all cells and filter by name.
    set all_cells [get_cells -hierarchical *]
    set buf_instances []
    foreach cell $all_cells {
        set cell_name [get_property $cell LEAF_CELL_NAME]
        if {[string match "BUF_*" $cell_name] || [string match "CLKBUF_*" $cell_name]} {
            # Check if this cell is driven by a clock net
            set inst_pins [get_pins -of_objects $cell]
            foreach pin $inst_pins {
                set pin_direction [get_property $pin DIRECTION]
                if {$pin_direction == "input"} {
                    set pin_net [get_nets -of_objects $pin]
                    # Check if the net is a clock net
                    set is_clock_net 0
                    foreach clk_n $clock_nets {
                        if {$pin_net eq $clk_n} {
                            set is_clock_net 1
                            break
                        }
                    }
                    if {$is_clock_net} {
                        lappend buf_instances $cell
                        break
                    }
                }
            }
        }
    }
}

# Create a dictionary to store level of each buffer instance
set buffer_levels [dict create]

# Create a dictionary to store parent of each buffer instance
set buffer_parents [dict create]

# Get the root net (connected to clk port)
set clk_port [get_ports clk]
set root_net [get_nets -of_objects $clk_port]

# Find all buffers driven by the root_net
foreach inst $buf_instances {
    # Get the input pin of the buffer
    set inst_pins [get_pins -of_objects $inst]
    set input_pin ""
    foreach pin $inst_pins {
        set pin_direction [get_property $pin DIRECTION]
        if {$pin_direction == "input"} {
            set input_pin $pin
            break
        }
    }

    if {$input_pin eq ""} {
        continue
    }

    set input_net [get_nets -of_objects $input_pin]

    # Check if this input_net is the root_net
    if {$input_net eq $root_net} {
        dict set buffer_levels $inst 1
        dict set buffer_parents $inst ""
    } else {
        # It's driven by another buffer. We'll resolve the level later.
        dict set buffer_levels $inst -1
        dict set buffer_parents $inst $input_net
    }
}

# Now, resolve levels for buffers not at level 1.
set changed 1
while {$changed} {
    set changed 0
    foreach inst $buf_instances {
        set level [dict get $buffer_levels $inst]
        if {$level == -1} {
            set parent_net [dict get $buffer_parents $inst]
            # Find the buffer driving this parent_net
            # The parent_net is driven by the output pin of some buffer.
            set drivers [get_cells -of_objects [get_pins -of_objects [get_nets -of_objects $parent_net] -filter "DIRECTION==output"]]
            # There should be exactly one buffer driving it (the parent)
            if {[llength $drivers] == 1} {
                set parent_inst [lindex $drivers 0]
                # Check if the parent is in our buffer list
                if {[dict exists $buffer_levels $parent_inst]} {
                    set parent_level [dict get $buffer_levels $parent_inst]
                    if {$parent_level != -1} {
                        dict set buffer_levels $inst [expr {$parent_level + 1}]
                        set changed 1
                    }
                }
            }
        }
    }
}

# Step 2: Count register sinks for each buffer.
# Register sinks are flip-flop clock pins driven directly by the buffer's output net.
set buffer_sink_counts [dict create]

foreach inst $buf_instances {
    set output_pin [get_pins -of_objects $inst -filter "DIRECTION==output"]
    if {[llength $output_pin] == 0} {
        dict set buffer_sink_counts $inst 0
        continue
    }
    set output_pin [lindex $output_pin 0]
    set output_net [get_nets -of_objects $output_pin]

    # Get all pins connected to this output_net
    set connected_pins [get_pins -of_objects $output_net]

    set sink_count 0
    foreach pin $connected_pins {
        # Check if this pin is a clock input of a flip-flop
        set parent_cell [get_cells -of_objects $pin]
        set cell_name [get_property $parent_cell LEAF_CELL_NAME]

        # Check if the pin is a clock pin
        set is_clock [get_property $pin IS_CLOCK]
        if {$is_clock} {
            # Check if the cell is a flip-flop
            # We can check if the cell is a leaf cell and has a clock input.
            # Exclude buffers, inverters, etc.
            set is_ff 0
            if {[string match "BUF*" $cell_name] || [string match "INV*" $cell_name]} {
                set is_ff 0
            } else {
                # Assume it's a register if it's not a buffer/inverter and has a clock pin
                set cell_pins [get_pins -of_objects $parent_cell]
                foreach cpin $cell_pins {
                    if {[get_property $cpin IS_CLOCK]} {
                        if {$pin eq $cpin} {
                            set is_ff 1
                            break
                        }
                    }
                }
            }

            if {$is_ff} {
                incr sink_count
            }
        }
    }
    dict set buffer_sink_counts $inst $sink_count
}

# Step 3: Write the output file.
set output_file "outputs/ct06_clock_tree.txt"
file delete -force $output_file
set fp [open $output_file w]

foreach inst $buf_instances {
    set inst_name $inst
    set cell_name [get_property $inst LEAF_CELL_NAME]
    set level [dict get $buffer_levels $inst]
    set sinks [dict get $buffer_sink_counts $inst]

    # Only write if level is resolved (not -1)
    if {$level != -1} {
        puts $fp "$inst_name $cell_name $level $sinks"
    }
}

close $fp

