# Get all IO ports
set io_ports [get_ports -filter "DIRECTION == INPUT || DIRECTION == OUTPUT || DIRECTION == INOUT"]

# Separate req_msg pins and others
set req_msg_pins []
set other_pins []

foreach port $io_ports {
    set name [get_name $port]
    if {[string match "req_msg[*]" $name]} {
        lappend req_msg_pins $name
    } else {
        lappend other_pins $name
    }
}

# Sort req_msg_pins by bit index to ensure left-to-right order
# The bit index is in brackets. We can sort them naturally.
# Tcl's sort with -dictionary might not handle [0] vs [10] correctly (10 before 2).
# We need to sort by the number inside the brackets.
# Let's create a list of pairs (bit_index, pin_name) and sort.
set sorted_req_msg_pins []
foreach pin $req_msg_pins {
    # Extract bit index
    if {[regexp {\[(\d+)\]$} $pin match bit_idx]} {
        lappend sorted_req_msg_pins [list $bit_idx $pin]
    }
}
# Sort by the numeric bit index
set sorted_pairs [lsort -integer -index 0 $sorted_req_msg_pins]
set req_msg_pins_sorted {}
foreach pair $sorted_pairs {
    lappend req_msg_pins_sorted [lindex $pair 1]
}

# Place req_msg pins on the bottom edge with metal2
place_pins -pins $req_msg_pins_sorted -side bottom -metal 2

# Place remaining pins on the left and right edges with metal3
# Split remaining pins into two lists for left and right
set num_other [llength $other_pins]
set half [expr {$num_other / 2}]
set left_pins [lrange $other_pins 0 [expr {$half - 1}]]
set right_pins [lrange $other_pins $half end]

if {[llength $left_pins] > 0} {
    place_pins -pins $left_pins -side left -metal 3
}
if {[llength $right_pins] > 0} {
    place_pins -pins $right_pins -side right -metal 3
}

