# Helper to count violations
proc count_violations {type} {
    set count 0
    set limit 0
    if {$type == "transition"} {
        set limit 0.05
        # Check output pins of all cells
        set pins [get_pins -filter "DIRECTION==OUTPUT && IS_LEAF==1"]
        foreach pin $pins {
            set val [get_property $pin transition]
            if {$val > $limit} {
                incr count
            }
        }
    } elseif {$type == "capacitance"} {
        set limit 10
        # Check input pins of all cells
        set pins [get_pins -filter "DIRECTION==INPUT && IS_LEAF==1"]
        foreach pin $pins {
            set val [get_property $pin load_capacitance]
            if {$val > $limit} {
                incr count
            }
        }
    } elseif {$type == "fanout"} {
        set limit 10
        # Check output pins of all cells
        set pins [get_pins -filter "DIRECTION==OUTPUT && IS_LEAF==1"]
        foreach pin $pins {
            set val [get_property $pin fanout]
            if {$val > $limit} {
                incr count
            }
        }
    }
    return $count
}

