proc calculate_hpwl {} {
    set total_hpwl 0
    # Get all nets
    foreach net [get_nets -hierarchical] {
        # Skip power and ground nets
        if {[string match "*GND*" [get_property $net name]] || [string match "*VDD*" [get_property $net name]] || [get_property $net is_power] || [get_property $net is_ground]} {
            continue
        }

        # Get pins of the net
        set pins [get_pins -of_objects $net]

        # Only consider nets with at least 2 pins
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 999999
        set max_x -999999
        set min_y 999999
        set max_y -999999

        foreach pin $pins {
            set loc [get_property $pin location]
            if {$loc == {}} {
                continue
            }
            set x [lindex $loc 0]
            set y [lindex $loc 1]

            if {$x < $min_x} {set min_x $x}
            if {$x > $max_x} {set max_x $x}
            if {$y < $min_y} {set min_y $y}
            if {$y > $max_y} {set max_y $y}
        }

        if {$min_x != 999999 && $max_x != -999999} {
            set hpwl [expr {($max_x - $min_x) + ($max_y - $min_y)}]
            set total_hpwl [expr {$total_hpwl + $hpwl}]
        }
    }
    return $total_hpwl
}

