# Helper function to flip orientation
proc flip_orientation {orient} {
    if {$orient == "N"} {
        return "S"
    } elseif {$orient == "S"} {
        return "N"
    } else {
        # Other orientations like E, W, N90, etc. might exist.
        # The task specifies "flip standard cells about their vertical (Y) axis".
        # In a standard row-based placement, cells are usually N or S.
        # If a cell is E or W, flipping about Y would map E->W and W->E?
        # Or N->S?
        # Let's assume standard cells are N/S. If other orientations exist, we need to handle them.
        # However, in Nangate45, standard cells are typically placed in N or S orientation.
        # Let's handle common cases.
        if {$orient == "E"} { return "W" }
        if {$orient == "W"} { return "E" }
        if {$orient == "N90"} { return "N270" } # Or S90?
        if {$orient == "S90"} { return "S270" } # Or N270?
        # For simplicity, if it's not N/S/E/W, we might skip or try to map.
        # But typically, row-based placement uses N and S.
        return $orient
    }
}

