# Step 2: Identify clock nets
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Error: Clock port clk not found"
    exit 1
}
set clk_net [get_nets -of_objects $clk_port]
if { [llength $clk_net] == 0 } {
    puts "Error: Net connected to clk port not found"
    exit 1
}

# Get all clock buffer instances
set clk_buf_cells [get_cells -hierarchical -filter "name =~ CLKBUF_*"]

# Collect all clock net names
set clock_nets [list]
lappend clock_nets [get_name $clk_net]

foreach cell $clk_buf_cells {
    # Get output pins of the clock buffer
    set out_pins [get_pins -of_objects $cell -filter "direction == output"]
    foreach pin $out_pins {
        set net [get_nets -of_objects $pin]
        if { [llength $net] > 0 } {
            set net_name [get_name $net]
            if { [lsearch -exact $clock_nets $net_name] == -1 } {
                lappend clock_nets $net_name
            }
        }
    }
}

# Step 3: Parse DEF file to get wirelengths
set def_file "outputs/clock_gr.def"
set div 10000.0 ;# Default assumption, will be overridden if DEF_UNITS is found

# Read DEF file and find DEF_UNITS
set def_content [read_file $def_file]
if { [regexp {DEF_UNITS\s+DATABASE\s+(\d+)} $def_content match div_str] } {
    set div [expr {1.0 / $div_str}]
} else {
    # Fallback: Nangate45 usually uses 10000
    set div 0.0001
}

# Parse ROUTE section
set current_net ""
set is_clock_net 0
set net_wirelengths [dict create]

# We need to parse the file line by line
set lines [split $def_content "\n"]
set in_route 0
set in_segment 0

foreach line $lines {
    # Remove leading/trailing whitespace
    set line [string trim $line]

    # Skip empty lines and comments
    if { $line eq "" || [string index $line 0] eq ";" } {
        continue
    }

    # Check for ROUTE keyword
    if { [string match "ROUTE*" $line] } {
        # Extract net name
        # Format: ROUTE net_name
        set parts [regexp -all -inline {\S+} $line]
        if { [llength $parts] >= 2 } {
            set current_net [lindex $parts 1]
            if { [lsearch -exact $clock_nets $current_net] != -1 } {
                set is_clock_net 1
                dict set net_wirelengths $current_net 0
            } else {
                set is_clock_net 0
            }
        } else {
            set current_net ""
            set is_clock_net 0
        }
        continue
    }

    # If we are tracking a clock net, look for SEGMENT
    if { $is_clock_net } {
        # Check for SEGMENT line
        # Format: SEGMENT layer_name x1 y1 x2 y2
        if { [string match "SEGMENT*" $line] } {
            set parts [regexp -all -inline {\S+} $line]
            if { [llength $parts] >= 5 } {
                # Parts: SEGMENT layer x1 y1 x2 y2
                set x1 [expr {double([lindex $parts 2])}]
                set y1 [expr {double([lindex $parts 3])}]
                set x2 [expr {double([lindex $parts 4])}]
                set y2 [expr {double([lindex $parts 5])}]

                set len [expr {abs($x1 - $x2) + abs($y1 - $y2)}]
                set current_len [dict get $net_wirelengths $current_net]
                dict set net_wirelengths $current_net [expr {$current_len + $len}]
            }
        }
    }
}

# Step 4: Write output file
set out_file "outputs/clock_gr_wirelength.txt"
set fh [open $out_file w]

foreach net_name [lsort [dict keys $net_wirelengths]] {
    set len_um [expr {[dict get $net_wirelengths $net_name] * $div}]
    puts $fh "$net_name $len_um"
}

close $fh

