openroad::rcx

# Report timing for a large number of paths to ensure we have enough candidates
set raw_timing [report_timing -max_paths 100]

# Parse the raw timing output to extract unique endpoints with worst slack
# We will store paths in a list of dicts: {slack, endpoint, path_text}
set paths_list {}
set current_path {}
set current_slack ""
set current_endpoint ""
set in_path 0

foreach line [split $raw_timing "\n"] {
    # Detect start of a new path
    if {[string match "Startpoint: *" $line]} {
        # If we were collecting a path, save it
        if {$in_path && $current_endpoint != ""} {
            lappend paths_list [list $current_slack $current_endpoint $current_path]
        }
        set current_path "$line\n"
        set in_path 1
        set current_slack ""
        set current_endpoint ""
    } elseif {$in_path} {
        set current_path "${current_path}$line\n"

        # Extract Slack
        if {[string match "Slack *" $line]} {
            # Slack line looks like: Slack (VIOLATED): -0.1234
            # Or: Slack (MET): 0.1234
            set slack_val [string trim [lindex [split $line " "] end]]
            set current_slack $slack_val
        }

        # Extract Endpoint
        if {[string match "Endpoint: *" $line]} {
            set current_endpoint [string trim [lindex [split $line " "] end]]
        }
    }
}
# Save the last path
if {$in_path && $current_endpoint != ""} {
    lappend paths_list [list $current_slack $current_endpoint $current_path]
}

# Sort paths by slack (numerically, worst first)
# We need to handle "VIOLATED" vs "MET" and negative/positive slacks.
# The slack_val extracted is just the number.
# We want worst (most negative) first.
set sorted_paths [lsort -real -increasing [lmap p $paths_list {
    # Extract the numeric slack from the stored string
    # The list is {slack_str endpoint path}
    lindex $p 0
}]]

# Re-associate slack with path
set sorted_paths_full {}
foreach slack_val $sorted_paths {
    foreach p $paths_list {
        if {[lindex $p 0] == $slack_val} {
            lappend sorted_paths_full $p
            break
        }
    }
}

# Select 10 unique endpoints
set seen_endpoints {}
set selected_paths {}
set count 0

foreach p $sorted_paths_full {
    if {$count >= 10} break
    set ep [lindex $p 1]
    if {![lsearch -exact $seen_endpoints $ep] != -1} {
        lappend seen_endpoints $ep
        lappend selected_paths $p
        incr count
    }
}

