# Run CTS with BUF_X8 as root and buffer
cts -root_buf BUF_X8 -buf BUF_X8

# Create output directory if it doesn't exist (though task says write to outputs/, assuming it exists)
# Since I can't use exec, I assume outputs/ is present.

# Get the main clock net (connected to port clk)
set clk_port [get_db_ports -name clk]
set clk_net [get_db_nets -of_objects $clk_port]

# 1. Number of clock roots
# Roots are the drivers of the main clock net
set root_drivers [get_db_insts -of_objects $clk_net -direction out]
set num_roots [llength $root_drivers]

# 2. Number of clock buffers inserted
# Count all BUF_X8 instances that are part of the clock tree.
# A simple heuristic: all BUF_X8 instances whose input or output nets are clock nets.
# More accurately, all BUF_X8 instances that are driven by a clock net or drive a clock net.
# Let's count all instances of BUF_X8.
set all_bufs [get_db_insts -of_lib_cells BUF_X8]
set num_buffers 0
foreach inst $all_bufs {
    # Check if this instance is connected to clock nets
    set inst_nets [get_db_nets -of_objects $inst]
    set is_clock_buf 0
    foreach net $inst_nets {
        # Check if net is a clock net. 
        # A net is a clock net if it is driven by a clock source or is part of the CTS tree.
        # Easier: Check if the net name starts with a typical CTS prefix or if it's connected to the clk port via the tree.
        # However, a more robust way in OpenROAD is to check if the net is a "clock" net type.
        # Let's assume any net connected to a BUF_X8 that is not the root net (which we counted separately) or is driven by the root net is a clock net.
        # Actually, let's just count all BUF_X8 instances. The task implies all inserted buffers are BUF_X8.
        # But we must ensure we don't count non-clock BUF_X8s if any exist (unlikely in this context).
        # Let's count all BUF_X8 instances.
        incr num_buffers
    }
}
# Refinement: The above counts all BUF_X8. Are there non-clock BUF_X8s? Unlikely in a simple CTS task.
# But to be precise, let's check if the net is connected to the clock tree.
# Reset and do it properly.
set num_buffers 0
foreach inst $all_bufs {
    # Get the output net of the buffer
    set out_pin [get_db_pins -of_objects $inst -direction out]
    if {[llength $out_pin] > 0} {
        set out_net [get_db_nets -of_objects $out_pin]
        if {[llength $out_net] > 0} {
            set net [lindex $out_net 0]
            # Check if this net is connected to the main clock net or driven by a clock buffer
            # A net is part of the clock tree if it is driven by a clock buffer or the root.
            # We can check if the driver of this net is a BUF_X8 or the root driver.
            set drivers [get_db_insts -of_objects $net -direction out]
            set is_clock_net 0
            foreach drv $drivers {
                set lib_cell [get_db_lib_cell -of_objects $drv]
                if {$lib_cell == "BUF_X8"} {
                    set is_clock_net 1
                    break
                }
                # Check if it's the root driver
                if {$drv in $root_drivers} {
                    set is_clock_net 1
                    break
                }
            }
            if {$is_clock_net} {
                incr num_buffers
            }
        }
    }
}

# 3. Number of clock subnets
# Nets driven by inserted clock buffers (BUF_X8)
set subnets [dict create]
foreach inst $all_bufs {
    set out_pin [get_db_pins -of_objects $inst -direction out]
    if {[llength $out_pin] > 0} {
        set out_net [get_db_nets -of_objects $out_pin]
        if {[llength $out_net] > 0} {
            set net [lindex $out_net 0]
            # Check if this net is a clock net (driven by a clock buffer or root)
            set drivers [get_db_insts -of_objects $net -direction out]
            set is_clock_net 0
            foreach drv $drivers {
                set lib_cell [get_db_lib_cell -of_objects $drv]
                if {$lib_cell == "BUF_X8"} {
                    set is_clock_net 1
                    break
                }
                if {$drv in $root_drivers} {
                    set is_clock_net 1
                    break
                }
            }
            if {$is_clock_net} {
                dict set subnets $net 1
            }
        }
    }
}
set num_subnets [dict size $subnets]

