# Get the clock port
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Error: Clock port 'clk' not found"
    exit 1
}
set clk_net [get_nets -of_objects $clk_port]

# Identify all CTS buffer instances
# The task states CTS uses BUF_X4 buffers.
set cts_buffers [get_cells -hierarchical -filter "CELL_NAME == BUF_X4"]

# If no BUF_X4 found, maybe it's CLKBUF? The platform says "CTS buffer BUF_X4".
# Let's stick to BUF_X4.

# Create a map to store level of each buffer
set buffer_levels {}

# BFS to determine levels
# Queue stores {instance_name level}
set queue {}
set visited_buffers {}

# Find Level 1 buffers: those driven directly by clk_net
# We need to find instances whose input pins are connected to clk_net
# And those instances are in cts_buffers list.

# Helper: get all instances driving a net (output pins of instances connected to net)
# Actually, we want instances whose *input* pins are on clk_net.
# So, get all pins on clk_net, filter for direction input, get the instance.

proc get_drivers_for_net { net_name } {
    set pins [get_pins -of_objects [get_nets $net_name]]
    set drivers {}
    foreach pin $pins {
        if { [get_property DIRECTION $pin] == "INPUT" } {
            set inst [get_property INSTANCE $pin]
            lappend drivers $inst
        }
    }
    return $drivers
}

# Helper: get the output net of a buffer instance
# Assuming single output pin for BUF_X4
proc get_buffer_output_net { inst_name } {
    set pins [get_pins -of_objects [get_cells $inst_name]]
    set out_pin ""
    foreach pin $pins {
        if { [get_property DIRECTION $pin] == "OUTPUT" } {
            set out_pin $pin
            break
        }
    }
    if { $out_pin != "" } {
        return [get_property NET $out_pin]
    }
    return ""
}

# Initialize BFS
set current_level_nets [list [get_name $clk_net]]
set current_level 1
set found_any_buffer 1

while { $found_any_buffer } {
    set found_any_buffer 0
    set next_level_nets {}

    foreach net_name $current_level_nets {
        # Find all instances driving this net
        set drivers [get_drivers_for_net $net_name]

        foreach inst $drivers {
            # Check if this instance is a CTS buffer
            if { [lsearch -exact $cts_buffers $inst] >= 0 } {
                # Check if already visited
                if { [lsearch -exact $visited_buffers $inst] < 0 } {
                    lappend visited_buffers $inst
                    set buffer_levels($inst) $current_level
                    set found_any_buffer 1

                    # Get output net for next level
                    set out_net [get_buffer_output_net $inst]
                    if { $out_net != "" } {
                        lappend next_level_nets $out_net
                    }
                }
            }
        }
    }

    if { $found_any_buffer } {
        incr current_level
        set current_level_nets $next_level_nets
    }
}

# Calculate register sinks for each buffer
# Register sink: a clock pin of a flip-flop driven directly by the buffer's output net.

# First, identify all FF clock pins
# How to identify an FF? We can look for instances that have a clock pin.
# Or check cell type. Common FF cells are DFF*, LATCH*, etc.
# A robust way: iterate all instances, if it has a pin with is_clock property true, it's a clock pin.
# But we need to know if the instance is an FF.
# Let's assume any instance with a clock pin is a sequential cell (FF/Latch).

set ff_clock_pins []
set all_instances [get_cells -hierarchical]

foreach inst $all_instances {
    set pins [get_pins -of_objects $inst]
    foreach pin $pins {
        if { [get_property IS_CLOCK $pin] == 1 } {
            lappend ff_clock_pins $pin
        }
    }
}

# Map: net_name -> count of ff_clock_pins on that net
# But we need per-buffer. So for each buffer, get its output net, then count ff_clock_pins on that net.

set output_file "outputs/ct06_clock_tree.txt"
file delete -force $output_file
file mkdir outputs

set output_lines {}

foreach inst [lsort $visited_buffers] {
    set level $buffer_levels($inst)
    set out_net [get_buffer_output_net $inst]
    set sink_count 0

    if { $out_net != "" } {
        # Count FF clock pins on this net
        foreach pin $ff_clock_pins {
            set pin_net [get_property NET $pin]
            if { $pin_net == $out_net } {
                incr sink_count
            }
        }
    }

    lappend output_lines "$inst [get_property CELL_NAME $inst] $level $sink_count"
}

# Write to file
set fid [open $output_file w]
foreach line $output_lines {
    puts $fid $line
}
close $fid

