# Function to get HPWL
proc get_hpwl {} {
    set hpwl_line [report_hpwl]
    if {[regexp {HPWL:\s+([\d\.]+)} $hpwl_line match hpwl_val]} {
        return $hpwl_val
    }
    return -1
}

# Initial HPWL
set initial_hpwl [get_hpwl]
if {$initial_hpwl == -1} {
    puts "ERROR: Could not get initial HPWL"
    exit 1
}
puts "Initial HPWL: $initial_hpwl"

set improved 1
set iterations 0
set max_iterations 10

while {$improved && $iterations < $max_iterations} {
    set improved 0
    set iterations [expr $iterations + 1]
    puts "Iteration $iterations..."

    set pass_hpwl [get_hpwl]

    foreach cell $std_cells {
        set current_orient [get_property orientation $cell]
        if {$current_orient == ""} continue

        set target_orient [dict get $mirror_map $current_orient]
        if {$target_orient == ""} continue
        if {$target_orient == $current_orient} continue

        set_property orientation $target_orient $cell

        set new_hpwl [get_hpwl]
        if {$new_hpwl != -1 && $new_hpwl < $pass_hpwl} {
            set pass_hpwl $new_hpwl
            set improved 1
        } else {
            set_property orientation $current_orient $cell
        }
    }
}

set final_hpwl [get_hpwl]
if {$final_hpwl != -1} {
    set reduction [expr ($initial_hpwl - $final_hpwl) / $initial_hpwl * 100]
    puts "Final HPWL: $final_hpwl"
    puts "Reduction: $reduction %"
    write_def outputs/gcd_legalized.def
} else {
    puts "ERROR: Could not get final HPWL"
}

# Function to calculate HPWL manually
proc calculate_hpwl {} {
    set total_hpwl 0
    set nets [get_nets -hierarchical -filter {IS_POWER == 0 && IS_GROUND == 0}]
    foreach net $nets {
        set pins [get_pins -hierarchical -of_objects $net]
        if {[llength $pins] < 2} continue

        set min_x 1e9
        set max_x -1e9
        set min_y 1e9
        set max_y -1e9

        foreach pin $pins {
            set inst [get_property instance $pin]
            if {$inst == ""} continue
            set x [get_property x $inst]
            set y [get_property y $inst]
            if {$x < $min_x} {set min_x $x}
            if {$x > $max_x} {set max_x $x}
            if {$y < $min_y} {set min_y $y}
            if {$y > $max_y} {set max_y $y}
        }

        set hpwl [expr {($max_x - $min_x) + ($max_y - $min_y)}]
        set total_hpwl [expr {$total_hpwl + $hpwl}]
    }
    return $total_hpwl
}

