# Function to calculate HPWL
# Excludes power and ground nets
# HPWL is sum of half-perimeter of bounding box for each net
proc calculate_hpwl {} {
    set total_hpwl 0.0
    set all_nets [get_nets [current_design]]

    foreach net $all_nets {
        set net_name [get_name $net]

        # Skip power and ground nets
        if {[string match -nocase "*VDD*" $net_name] || [string match -nocase "*GND*" $net_name]} {
            continue
        }

        # Get all pins and filter by net name
        set all_pins [get_pins -hierarchical]
        set pins [list]
        foreach pin $all_pins {
            if {[get_property net $pin] eq $net} {
                lappend pins $pin
            }
        }

        # Skip nets with fewer than 2 pins
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 1e9
        set min_y 1e9
        set max_x -1e9
        set max_y -1e9

        foreach pin $pins {
            # Get the location of the pin
            set loc [get_property location $pin]

            if {$loc != ""} {
                set x [lindex $loc 0]
                set y [lindex $loc 1]

                if {$x < $min_x} {set min_x $x}
                if {$x > $max_x} {set max_x $x}
                if {$y < $min_y} {set min_y $y}
                if {$y > $max_y} {set max_y $y}
            }
        }

        # If any pin location was missing, skip this net
        if {$min_x == 1e9} {
            continue
        }

        set width [expr {$max_x - $min_x}]
        set height [expr {$max_y - $min_y}]
        set hpwl_net [expr {($width + $height) / 2.0}]

        set total_hpwl [expr {$total_hpwl + $hpwl_net}]
    }

    return $total_hpwl
}

