set buffer_sinks [dict create]

# Identify the clock root network
set clk_port [get_ports clk]
if {[llength $clk_port] != 1} {
    puts "Error: Could not find exactly one port named clk"
    exit 1
}
set clk_net [get_nets -of_objects $clk_port]
if {[llength $clk_net] != 1} {
    puts "Error: Could not find exactly one net driven by clk port"
    exit 1
}
set root_net [lindex $clk_net 0]

# Function to get driven buffers from a net
proc get_driven_buffers_from_net {net_name} {
    set out_pins [get_pins -of_objects [get_nets $net_name] -filter "DIRECTION == OUT"]
    set driven_cells [get_cells -of_objects $out_pins]

    set cts_drivers [lmap cell $driven_cells {
        set cell_name [get_property CELL_NAME $cell]
        if {$cell_name == "BUF_X4"} {
            get_property NAME $cell
        }
    }]
    set cts_drivers [lsearch -all -inline -not -exact $cts_drivers ""]
    return $cts_drivers
}

# Function to get driven FF clock pins from a net
proc get_driven_ff_clock_pins_from_net {net_name} {
    set driven_pins [get_pins -of_objects [get_nets $net_name] -filter "DIRECTION == IN && IS_CLOCK == 1"]
    set ff_count 0
    foreach pin $driven_pins {
        set cell [get_cells -of_objects $pin]
        set cell_name [get_property CELL_NAME $cell]

        set is_basic_cell 0
        if {[string match "BUF_*" $cell_name] || \
            [string match "INV_*" $cell_name] || \
            [string match "CLKBUF_*" $cell_name] || \
            [string match "TAPCELL_*" $cell_name] || \
            [string match "FILLCELL_*" $cell_name] || \
            [string match "TIEHI_*" $cell_name] || \
            [string match "TIELO_*" $cell_name]} {
            set is_basic_cell 1
        }

        if {!$is_basic_cell} {
            incr ff_count
        }
    }
    return $ff_count
}

# Build the graph
set level1_buffers [get_driven_buffers_from_net $root_net]

set downstream_graph [dict create]

foreach buf_name $cts_buffer_set {
    set buf_cell [get_cells * $buf_name]

    set out_pins [get_pins -of_objects $buf_cell -filter "DIRECTION == OUT"]
    if {[llength $out_pins] != 1} {
        puts "Warning: Buffer $buf_name has [llength $out_pins] output pins"
    }

    set out_pin [lindex $out_pins 0]
    set out_net [get_property NET $out_pin]

    set downstream_buffers [get_driven_buffers_from_net $out_net]
    dict set downstream_graph $buf_name $downstream_buffers

    set ff_sinks [get_driven_ff_clock_pins_from_net $out_net]
    dict set buffer_sinks $buf_name $ff_sinks
}

# Assign levels using BFS
set queue [list]
foreach buf $level1_buffers {
    dict set buffer_level $buf 1
    lappend queue "$buf 1"
}

if {[llength $level1_buffers] == 0} {
    puts "Warning: No level 1 buffers found."
}

set visited [dict create]

while {[llength $queue] > 0} {
    set current [lindex $queue 0]
    set queue [lrange $queue 1 end]

    set buf_name [lindex $current 0]
    set current_level [lindex $current 1]

    if {[dict exists $visited $buf_name]} {
        continue
    }
    dict set visited $buf_name 1

    if {[dict exists $downstream_graph $buf_name]} {
        set downstream [dict get $downstream_graph $buf_name]
        foreach next_buf $downstream {
            if {![dict exists $visited $next_buf]} {
                set next_level [expr {$current_level + 1}]

                if {[dict exists $buffer_level $next_buf]} {
                    set existing_level [dict get $buffer_level $next_buf]
                    if {$existing_level > $next_level} {
                        dict set buffer_level $next_buf $next_level
                        lappend queue "$next_buf $next_level"
                    }
                } else {
                    dict set buffer_level $next_buf $next_level
                    lappend queue "$next_buf $next_level"
                }
            }
        }
    }
}

# Write output
file mkdir outputs
set output_file outputs/ct06_clock_tree.txt
set fid [open $output_file w]

set sorted_buffers [lsort $cts_buffer_set]

foreach buf_name $sorted_buffers {
    set level [dict get $buffer_level $buf_name]
    set sinks [dict get $buffer_sinks $buf_name]

    if {![dict exists $buffer_level $buf_name]} {
        puts "Warning: Buffer $buf_name has no level assigned."
        set level 0
    }

    set cell_name [get_property CELL_NAME [get_cells * $buf_name]]

    puts "$buf_name $cell_name $level $sinks" >> $output_file
}

close $fid

