set all_nets [get_nets -of_objects [get_cells -hierarchical $design]]

# Identify clock net
# The clock port is 'clk'
set clk_port [get_ports clk]
set clock_net [get_nets -of_objects $clk_port]

# Identify power/ground nets
# Get all ports
set all_ports [get_ports]
set pg_nets {}
foreach port $all_ports {
    set port_name [get_property NAME $port]
    if {[string match -nocase "VDD*" $port_name] || [string match -nocase "VSS*" $port_name] || [string match -nocase "GND*" $port_name]} {
        set nets [get_nets -of_objects $port]
        foreach net $nets {
            lappend pg_nets $net
        }
    }
}

# Filter out clock and power/ground nets
set signal_nets {}
foreach net $all_nets {
    set net_name [get_property NAME $net]

    # Skip clock net
    if {$net eq $clock_net} {
        continue
    }

    # Skip power/ground nets
    set is_pg 0
    foreach pg_net $pg_nets {
        if {$net eq $pg_net} {
            set is_pg 1
            break
        }
    }
    if {$is_pg} {
        continue
    }

    lappend signal_nets $net
}

# Calculate fanout for each signal net
set net_fanouts {}
foreach net $signal_nets {
    # Get all pins connected to this net
    set pins [get_pins -of_objects [get_nets $net]]

    # Count sinks: output pins of instances (not the driver) and top-level output ports
    # The driver is the pin that drives the net. Sinks are the rest.
    # A simpler way: count all output pins of instances connected to the net, plus top-level output ports.
    # But we need to exclude the driver.

    # Let's count all sinks first
    set sink_count 0

    # Get instances connected to this net
    set instances [get_cells -hierarchical -of_objects $net]

    # For each instance, check its pins connected to the net
    foreach inst $instances {
        # Get pins of this instance connected to the net
        set inst_pins [get_pins -of_objects $inst -filter "NET == $net"]
        foreach pin $inst_pins {
            set pin_direction [get_property DIRECTION $pin]
            if {$pin_direction eq "OUTPUT"} {
                incr sink_count
            }
        }
    }

    # Also count top-level output ports connected to this net
    set ports [get_ports -of_objects $net]
    foreach port $ports {
        set port_direction [get_property DIRECTION $port]
        if {$port_direction eq "OUTPUT"} {
            incr sink_count
        }
    }

    lappend net_fanouts "$net_name $sink_count"
}

# Sort by fanout descending
# Format: net_name fanout
set sorted_nets [lsort -decreasing -index 2 -real $net_fanouts]

# Take top 5
set top5 [lrange $sorted_nets 0 4]

