# 1. Analyze Flip-Flop Types
# Get all leaf instances (cells)
set all_leaf_instances [get_cells -hierarchical -filter "IS_HIERARCHICAL == 0"]

set flop_type_counts [dict create]
set total_flops 0

foreach inst $all_leaf_instances {
    # Get the leaf cell type
    set cell_type [get_property LEAF_CELL $inst]

    # Check if it's a flip-flop
    # Common patterns: DFF*, DFFR*, DFFS*, DFFE*, TFF*, JKFF*, etc.
    if { [string match "*FF*" $cell_type] } {
        if { [dict exists $flop_type_counts $cell_type] } {
            set current_count [dict get $flop_type_counts $cell_type]
            dict set flop_type_counts $cell_type [expr $current_count + 1]
        } else {
            dict set flop_type_counts $cell_type 1
        }
        incr total_flops
    }
}

# Write flop_types.txt
foreach cell_type [lsort [dict keys $flop_type_counts]] {
    puts $flop_types_file "$cell_type [dict get $flop_type_counts $cell_type]"
}
puts $flop_types_file "total $total_flops"

# 2. Analyze Flip-Flop Clock Drivers
set driver_counts [dict create]

# Iterate through all leaf instances again to find flip-flops and their clock drivers
foreach inst $all_leaf_instances {
    set cell_type [get_property LEAF_CELL $inst]

    # Check if it's a flip-flop
    if { [string match "*FF*" $cell_type] } {
        # Find the clock pin. Common names: CLK, CK
        # We need to get the pins of this instance
        set pins [get_pins -of_objects $inst]

        set clk_pin [get_pins -of_objects $inst -filter "NAME == CLK || NAME == CK || NAME == CLK_N || NAME == CK_N"]

        if { [llength $clk_pin] > 0 } {
            set pin [lindex $clk_pin 0]
            set net [get_nets -of_objects $pin]

            if { [llength $net] > 0 } {
                set net_obj [lindex $net 0]

                # Get the driving pin of this net
                # The driver is the output pin of the cell connected to this net
                set driving_pins [get_pins -of_objects $net_obj -direction OUT]

                if { [llength $driving_pins] > 0 } {
                    set driver_pin [lindex $driving_pins 0]
                    set driver_cell [get_cells -of_objects $driver_pin]

                    # Get the instance name of the driver
                    # The driver_cell is the cell type instance. We need its instance name.
                    # If driver_cell is a leaf cell, its instance name is the same as the cell name if it's the only instance?
                    # No, get_cells returns the cell object. We need the instance name.
                    # Use get_property INSTANCE_NAME on the cell? No, INSTANCE_NAME is on the instance.
                    # The driver_pin belongs to an instance. We can get the instance from the pin.
                    set driver_inst_name [get_property INSTANCE_NAME $driver_pin]

                    if { $driver_inst_name != "" } {
                        if { [dict exists $driver_counts $driver_inst_name] } {
                            set current_count [dict get $driver_counts $driver_inst_name]
                            dict set driver_counts $driver_inst_name [expr $current_count + 1]
                        } else {
                            dict set driver_counts $driver_inst_name 1
                        }
                    }
                }
            }
        }
    }
}

