# Helper to get pin center
proc get_pin_center {pin} {
    set shapes [get_db_pin_shapes $pin]
    if {[llength $shapes] == 0} {
        return [list 0 0]
    }
    set min_x [lindex [get_db_shape_bounding_box [lindex $shapes 0]] 0]
    set min_y [lindex [get_db_shape_bounding_box [lindex $shapes 0]] 1]
    set max_x [lindex [get_db_shape_bounding_box [lindex $shapes 0]] 2]
    set max_y [lindex [get_db_shape_bounding_box [lindex $shapes 0]] 3]

    foreach shape $shapes {
        set bbox [get_db_shape_bounding_box $shape]
        set x1 [lindex $bbox 0]
        set y1 [lindex $bbox 1]
        set x2 [lindex $bbox 2]
        set y2 [lindex $bbox 3]
        if {$x1 < $min_x} {set min_x $x1}
        if {$y1 < $min_y} {set min_y $y1}
        if {$x2 > $max_x} {set max_x $x2}
        if {$y2 > $max_y} {set max_y $y2}
    }
    set center_x [expr {($min_x + $max_x) / 2.0}]
    set center_y [expr {($min_y + $max_y) / 2.0}]
    return [list $center_x $center_y]
}

# Function to calculate HPWL
proc calculate_hpwl {design} {
    set total_hpwl 0
    set nets [get_nets -design $design]

    foreach net $nets {
        set name [get_property $net name]
        # Filter out power and ground nets
        if {[string match -nocase "*VDD*" $name] || \
            [string match -nocase "*GND*" $name] || \
            [string match -nocase "*VPWR*" $name] || \
            [string match -nocase "*VGND*" $name] || \
            [string match -nocase "*VSS*" $name]} {
            continue
        }

        set pins [get_db_nets_pins $net]
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 1e9
        set min_y 1e9
        set max_x -1e9
        set max_y -1e9

        foreach pin $pins {
            set center [get_pin_center $pin]
            set x [lindex $center 0]
            set y [lindex $center 1]

            if {$x < $min_x} {set min_x $x}
            if {$y < $min_y} {set min_y $y}
            if {$x > $max_x} {set max_x $x}
            if {$y > $max_y} {set max_y $y}
        }

        set hpwl [expr {($max_x - $min_x) + ($max_y - $min_y)}]
        set total_hpwl [expr {$total_hpwl + $hpwl}]
    }
    return $total_hpwl
}

