        }

        # Get pins for the net
        set pins [get_db_net_pins $net]
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 1e9
        set min_y 1e9
        set max_x -1e9
        set max_y -1e9

        foreach pin $pins {
            set center [get_pin_center $pin]
            set x [lindex $center 0]
            set y [lindex $center 1]

            if {$x < $min_x} {set min_x $x}
            if {$y < $min_y} {set min_y $y}
            if {$x > $max_x} {set max_x $x}
            if {$y > $max_y} {set max_y $y}
        }

        set hpwl [expr {($max_x - $min_x) + ($max_y - $min_y)}]
        set total_hpwl [expr {$total_hpwl + $hpwl}]
    }
    return $total_hpwl
}

