# Read the timing report file
set fid [open $timing_file r]
set content [read $fid]
close $fid

# Parse WNS and TNS from the report
# The report_timing output usually ends with a summary line like:
# "WNS: -0.0377 TNS: -0.0772" or similar.
# We can use regex to find these values.

set wns -1e10
set tns 0

# Try to find WNS and TNS in the report
if {[regexp -all -line "WNS:?\s*(-?[0-9]+\.[0-9]+)" $content match wns_val]} {
    set wns $wns_val
}

if {[regexp -all -line "TNS:?\s*(-?[0-9]+\.[0-9]+)" $content match tns_val]} {
    set tns $tns_val
}

# If WNS or TNS were not found, we might need to parse individual path slacks.
# However, the report_timing summary usually contains these values.
# If the above regex fails, we can try to get the worst slack and sum negative slacks by parsing each path.

if {$wns == -1e10} {
    # Fallback: parse individual path slacks
    set wns 0
    set tns 0
    set found_any 0

    # Split the content into lines
    set lines [split $content "\n"]
    foreach line $lines {
        # Look for lines with slack information, e.g., "slack: -0.0377"
        if {[regexp "slack:\s*(-?[0-9]+\.[0-9]+)" $line match slack_val]} {
            set slack $slack_val
            set found_any 1
            if {$found_any == 1} {
                if {$slack < $wns} {
                    set wns $slack
                }
                if {$slack < 0} {
                    set tns [expr {$tns + $slack}]
                }
                set found_any 0
            } else {
                set wns $slack
                set tns 0
                if {$slack < 0} {
                    set tns $slack
                }
                set found_any 1
            }
        }
    }

    if {$found_any == 0} {
        set wns 0
        set tns 0
    }
}

