# State variable to track which section we are in
set current_section ""

foreach line $lines {
    # Check for section headers
    if {[string match "*Max Transition Violations*" $line]} {
        set current_section "transition"
        continue
    }
    if {[string match "*Max Capacitance Violations*" $line]} {
        set current_section "capacitance"
        continue
    }

    # If we are in a violation section, extract the pin name
    # The format is usually "  Instance/Pin: ..." or just "  Instance/Pin"
    # We need to be careful to only pick up lines that look like pin names
    if {$current_section == "transition"} {
        # Skip empty lines or summary lines
        if {[string trim $line] ne "" && ![string match "*Total*" $line] && ![string match "*Count*" $line]} {
            # Extract the pin name. Assuming format "  Instance/Pin: value" or "  Instance/Pin"
            # We can just take the whole line if it's a pin entry, but let's clean it up
            set pin [string trim $line]
            # Remove any trailing colon or value if present, though the task says "name every violating pin"
            # The standard report usually lists the pin name.
            # Let's assume the line contains the pin name.
            # If the line is "  inst/pin: 0.06 ns", we want "inst/pin"
            if {[string match "*:*" $pin]} {
                set pin [lindex [split $pin ":"] 0]
            }
            lappend transition_violations $pin
        }
    } elseif {$current_section == "capacitance"} {
        if {[string trim $line] ne "" && ![string match "*Total*" $line] && ![string match "*Count*" $line]} {
            set pin [string trim $line]
            if {[string match "*:*" $pin]} {
                set pin [lindex [split $pin ":"] 0]
            }
            lappend capacitance_violations $pin
        }
    }
}

