# 4. Timing Analysis
# We need to report timing to get slack values.
# We will report setup and hold timing with all paths to calculate the required metrics.

# Report Setup Timing (max delay)
# We use a large number of paths to ensure we capture all endpoints.
set setup_report [report_timing -delay max -nworst 100000 -max_paths 100000 -fields {slack}]

# Report Hold Timing (min delay)
set hold_report [report_timing -delay min -nworst 100000 -max_paths 100000 -fields {slack}]

# Helper procedure to parse slacks from the report
# The output of report_timing -fields {slack} typically contains lines like "slack: -0.1234"
proc parse_slacks {report} {
    set slacks [list]
    foreach line [split $report "\n"] {
        if {[regexp {slack:\s*(-?[0-9]+\.[0-9]+)} $line match slack_val]} {
            lappend slacks $slack_val
        }
    }
    return $slacks
}

# Parse the slacks
set setup_slacks [parse_slacks $setup_report]
set hold_slacks [parse_slacks $hold_report]

# Calculate Setup Metrics
set worst_setup_slack 0.0
set total_negative_setup_slack 0.0
set setup_violating_endpoints 0

foreach slack $setup_slacks {
    if {$slack < $worst_setup_slack} {
        set worst_setup_slack $slack
    }
    if {$slack < 0} {
        set total_negative_setup_slack [expr {$total_negative_setup_slack + $slack}]
        incr setup_violating_endpoints
    }
}

# Calculate Hold Metrics
set worst_hold_slack 0.0
if {[llength $hold_slacks] > 0} {
    set worst_hold_slack [lindex $hold_slacks 0]
    foreach slack $hold_slacks {
        if {$slack < $worst_hold_slack} {
            set worst_hold_slack $slack
        }
    }
} else {
    # If no hold paths, worst hold slack is typically 0 or a large positive value.
    # However, in a routed design, there should be hold paths.
    set worst_hold_slack 0.0
}

# Format the output values
set worst_setup_slack_str [format "%.4f" $worst_setup_slack]
set total_negative_setup_slack_str [format "%.4f" $total_negative_setup_slack]
set worst_hold_slack_str [format "%.4f" $worst_hold_slack]
set setup_violating_endpoints_str [format "%d" $setup_violating_endpoints]

